44         //------------------------------------------------------------------------------
45         // Abstract interface representing any effect which can be applied onto a D3D device context.
46         class IEffect
47         {
48         public:
49             virtual ~IEffect() = default;
50 
51             IEffect(const IEffect&) = delete;
52             IEffect& operator=(const IEffect&) = delete;
53 
54             virtual void __cdecl Apply(_In_ ID3D12GraphicsCommandList* commandList) = 0;
55 
56         protected:
57             IEffect() = default;
58             IEffect(IEffect&&) = default;
59             IEffect& operator=(IEffect&&) = default;
60         };
61 
62 
63         // Abstract interface for effects with world, view, and projection matrices.
64         class IEffectMatrices
65         {
66         public:
67             virtual ~IEffectMatrices() = default;
68 
69             IEffectMatrices(const IEffectMatrices&) = delete;
70             IEffectMatrices& operator=(const IEffectMatrices&) = delete;
71 
72             virtual void XM_CALLCONV SetWorld(FXMMATRIX value) = 0;
73             virtual void XM_CALLCONV SetView(FXMMATRIX value) = 0;
74             virtual void XM_CALLCONV SetProjection(FXMMATRIX value) = 0;
75             virtual void XM_CALLCONV SetMatrices(FXMMATRIX world, CXMMATRIX view, CXMMATRIX projection);
76 
77         protected:
78             IEffectMatrices() = default;
79             IEffectMatrices(IEffectMatrices&&) = default;
80             IEffectMatrices& operator=(IEffectMatrices&&) = default;
81         };
