84         // Abstract interface for effects which support directional lighting.
85         class IEffectLights
86         {
87         public:
88             virtual ~IEffectLights() = default;
89 
90             IEffectLights(const IEffectLights&) = delete;
91             IEffectLights& operator=(const IEffectLights&) = delete;
92 
93             virtual void XM_CALLCONV SetAmbientLightColor(FXMVECTOR value) = 0;
94 
95             virtual void __cdecl SetLightEnabled(int whichLight, bool value) = 0;
96             virtual void XM_CALLCONV SetLightDirection(int whichLight, FXMVECTOR value) = 0;
97             virtual void XM_CALLCONV SetLightDiffuseColor(int whichLight, FXMVECTOR value) = 0;
98             virtual void XM_CALLCONV SetLightSpecularColor(int whichLight, FXMVECTOR value) = 0;
99 
100             virtual void __cdecl EnableDefaultLighting() = 0;
101 
102             static constexpr int MaxDirectionalLights = 3;
103 
104         protected:
105             IEffectLights() = default;
106             IEffectLights(IEffectLights&&) = default;
107             IEffectLights& operator=(IEffectLights&&) = default;
108         };
