152         //------------------------------------------------------------------------------
153         namespace EffectFlags
154         {
155             constexpr uint32_t None = 0x00;
156             constexpr uint32_t Fog = 0x01;
157             constexpr uint32_t Lighting = 0x02;
158 
159             constexpr uint32_t PerPixelLighting = 0x04 | Lighting;
160             // per pixel lighting implies lighting enabled
161 
162             constexpr uint32_t VertexColor = 0x08;
163             constexpr uint32_t Texture = 0x10;
164             constexpr uint32_t Instancing = 0x20;
165 
166             constexpr uint32_t Specular = 0x100;
167             // enable optional specular/specularMap feature
168 
169             constexpr uint32_t Emissive = 0x200;
170             // enable optional emissive/emissiveMap feature
171 
172             constexpr uint32_t Fresnel = 0x400;
173             // enable optional Fresnel feature
174 
175             constexpr uint32_t Velocity = 0x800;
176             // enable optional velocity feature
177 
178             constexpr uint32_t BiasedVertexNormals = 0x10000;
179             // compressed vertex normals need x2 bias
180         }
