184         // Built-in shader supports optional texture mapping, vertex coloring, directional lighting, and fog.
185         class BasicEffect : public IEffect, public IEffectMatrices, public IEffectLights, public IEffectFog
186         {
187         public:
188             BasicEffect(_In_ ID3D12Device* device, uint32_t effectFlags, const EffectPipelineStateDescription& pipelineDescription);
189 
190             BasicEffect(BasicEffect&&) noexcept;
191             BasicEffect& operator= (BasicEffect&&) noexcept;
192 
193             BasicEffect(BasicEffect const&) = delete;
194             BasicEffect& operator= (BasicEffect const&) = delete;
195 
196             ~BasicEffect() override;
197 
198             // IEffect methods.
199             void __cdecl Apply(_In_ ID3D12GraphicsCommandList* commandList) override;
200 
201             // Camera settings.
202             void XM_CALLCONV SetWorld(FXMMATRIX value) override;
203             void XM_CALLCONV SetView(FXMMATRIX value) override;
204             void XM_CALLCONV SetProjection(FXMMATRIX value) override;
205             void XM_CALLCONV SetMatrices(FXMMATRIX world, CXMMATRIX view, CXMMATRIX projection) override;
206 
207             // Material settings.
208             void XM_CALLCONV SetDiffuseColor(FXMVECTOR value);
209             void XM_CALLCONV SetEmissiveColor(FXMVECTOR value);
210             void XM_CALLCONV SetSpecularColor(FXMVECTOR value);
211             void __cdecl SetSpecularPower(float value);
212             void __cdecl DisableSpecular();
213             void __cdecl SetAlpha(float value);
214             void XM_CALLCONV SetColorAndAlpha(FXMVECTOR value);
215 
216             // Light settings.
217             void XM_CALLCONV SetAmbientLightColor(FXMVECTOR value) override;
218 
219             void __cdecl SetLightEnabled(int whichLight, bool value) override;
220             void XM_CALLCONV SetLightDirection(int whichLight, FXMVECTOR value) override;
221             void XM_CALLCONV SetLightDiffuseColor(int whichLight, FXMVECTOR value) override;
222             void XM_CALLCONV SetLightSpecularColor(int whichLight, FXMVECTOR value) override;
223 
224             void __cdecl EnableDefaultLighting() override;
225 
226             // Fog settings.
227             void __cdecl SetFogStart(float value) override;
228             void __cdecl SetFogEnd(float value) override;
229             void XM_CALLCONV SetFogColor(FXMVECTOR value) override;
230 
231             // Texture setting.
232             void __cdecl SetTexture(D3D12_GPU_DESCRIPTOR_HANDLE srvDescriptor, D3D12_GPU_DESCRIPTOR_HANDLE samplerDescriptor);
233 
234         private:
235             // Private implementation.
236             class Impl;
237 
238             std::unique_ptr<Impl> pImpl;
239         };
