782         //------------------------------------------------------------------------------
783         // Abstract interface to factory for sharing effects
784         class IEffectFactory
785         {
786         public:
787             virtual ~IEffectFactory() = default;
788 
789             IEffectFactory(const IEffectFactory&) = delete;
790             IEffectFactory& operator=(const IEffectFactory&) = delete;
791 
792             struct EffectInfo
793             {
794                 std::wstring        name;
795                 bool                perVertexColor;
796                 bool                enableSkinning;
797                 bool                enableDualTexture;
798                 bool                enableNormalMaps;
799                 bool                biasedVertexNormals;
800                 float               specularPower;
801                 float               alphaValue;
802                 XMFLOAT3            ambientColor;
803                 XMFLOAT3            diffuseColor;
804                 XMFLOAT3            specularColor;
805                 XMFLOAT3            emissiveColor;
806                 int                 diffuseTextureIndex;
807                 int                 specularTextureIndex;
808                 int                 normalTextureIndex;
809                 int                 emissiveTextureIndex;
810                 int                 samplerIndex;
811                 int                 samplerIndex2;
812 
813                 EffectInfo() noexcept
814                     : perVertexColor(false)
815                     , enableSkinning(false)
816                     , enableDualTexture(false)
817                     , enableNormalMaps(false)
818                     , biasedVertexNormals(false)
819                     , specularPower(0)
820                     , alphaValue(0)
821                     , ambientColor(0, 0, 0)
822                     , diffuseColor(0, 0, 0)
823                     , specularColor(0, 0, 0)
824                     , emissiveColor(0, 0, 0)
825                     , diffuseTextureIndex(-1)
826                     , specularTextureIndex(-1)
827                     , normalTextureIndex(-1)
828                     , emissiveTextureIndex(-1)
829                     , samplerIndex(-1)
830                     , samplerIndex2(-1)
831                 {
832                 }
833             };
834 
835             virtual std::shared_ptr<IEffect> __cdecl CreateEffect(
836                 const EffectInfo& info,
837                 const EffectPipelineStateDescription& opaquePipelineState,
838                 const EffectPipelineStateDescription& alphaPipelineState,
839                 const D3D12_INPUT_LAYOUT_DESC& inputLayout,
840                 int textureDescriptorOffset = 0,
841                 int samplerDescriptorOffset = 0) = 0;
842 
843         protected:
844             IEffectFactory() = default;
845             IEffectFactory(IEffectFactory&&) = default;
846             IEffectFactory& operator=(IEffectFactory&&) = default;
847         };
848 
